// zeroInvalid reports the model that makes a type's zero value invalid.
func (c *checker) zeroInvalid(typ types.Type) (*model, bool) {
	return c.zero(typ, make(map[types.Type]bool))
}

// zero walks one type and stops named recursion through types already seen.
func (c *checker) zero(typ types.Type, seen map[types.Type]bool) (*model, bool) {
	if typ == nil {
		return nil, false
	}
	typ = types.Unalias(typ)
	if seen[typ] {
		return nil, false
	}
	seen[typ] = true
	if model := c.modelFor(typ); model != nil {
		return model, true
	}
	classified := goTypeOf(typ)
	switch classified.Tag() {
	case goTypeTagNamed:
		return c.zero(classified.NamedPayload().Value.Underlying(), seen)
	case goTypeTagStruct:
		structure := classified.StructPayload().Value
		for index := 0; index < structure.NumFields(); index++ {
			if model, invalid := c.zero(structure.Field(index).Type(), seen); invalid {
				return model, true
			}
		}
	case goTypeTagArray:
		array := classified.ArrayPayload().Value
		if array.Len() > 0 {
			return c.zero(array.Elem(), seen)
		}
	case goTypeTagTypeParameter:
		parameter := classified.TypeParameterPayload().Value
		if model := c.zeroTypes[parameter]; model != nil {
			return model, true
		}
		terms, supported := simpleTerms(parameter.Constraint())
		if !supported {
			return nil, false
		}
		for _, term := range terms {
			if model, invalid := c.zero(term.Type(), make(map[types.Type]bool)); invalid {
				return model, true
			}
		}
	case goTypeTagNil, goTypeTagBasic, goTypeTagSlice, goTypeTagPointer,
		goTypeTagTuple, goTypeTagSignature, goTypeTagMap, goTypeTagChannel,
		goTypeTagInterface, goTypeTagUnion, goTypeTagOther:
	default:
		panic("invalid goType tag") // unreachable: tgolint requires a case per tag
	}
	return nil, false
}

// checkValueSpec rejects declarations that create an invalid model zero.
func (c *checker) checkValueSpec(specification *syntax.ValueSpecification) {
	if len(specification.Values) != 0 {
		return
	}
	for _, name := range specification.Names {
		object, ok := c.facts.DefinitionName(name).(*types.Var)
		if !ok {
			continue
		}
		if model, invalid := c.zeroInvalid(object.Type()); invalid {
			c.pass.Reportf(name.Start,
				"zero declaration contains invalid tgo %s %s; construct it first",
				modelKind(model), modelName(model))
		}
	}
}

// checkNamedResults rejects implicit zero values in named function results.
func (c *checker) checkNamedResults(function *syntax.FunctionType) {
	if function.Results == nil {
		return
	}
	for _, field := range function.Results.List {
		for _, name := range field.Names {
			object, ok := c.facts.DefinitionName(name).(*types.Var)
			if !ok {
				continue
			}
			if model, invalid := c.zeroInvalid(object.Type()); invalid {
				c.pass.Reportf(name.Start,
					"named result contains invalid tgo %s %s zero; use an unnamed result",
					modelKind(model), modelName(model))
			}
		}
	}
}

// checkLiteral finds omitted elements that receive an invalid model zero.
